            Describe.Lean(DescribeId.Create("original-normal-row-source-normalmean"), DeclarationHandle.Create(Prefix + "normalMean"), H("normalMean"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("The source mean is zero; input and output means are the original negative charge pairings."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("original-normal-row-source-normalweight"), DeclarationHandle.Create(Prefix + "normalWeight"), H("normalWeight"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("Source frequency r has weight -2r; an input mode has weight minus (2n+1), and an output mode has weight plus (2n+1)."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("original-normal-row-source-original-normal-row-finite"), DeclarationHandle.Create(Prefix + "original_normal_row_finite"), H("original_normal_row_finite"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("For every finite embedding into the original oscillator indices, all three occupations, arbitrary charge, every integer exponent and the original determinant-unit hypothesis, the actual signed Wick row of oscillatorNormal equals the product of all three factorial weights times the ordinary Gaussian Laurent coefficient at e+chargeNorm(a)."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-normal-row-source-normallaurentrow"), DeclarationHandle.Create(Prefix + "normalLaurentRow"), H("normalLaurentRow"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("Use exactly the union of the three occupation supports, including the empty union. The finite polynomial exponential is summed through total occupation degree, and the auxiliary coordinate is specialized by a bounded coefficient sum."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("original-normal-row-source-original-normal-row"), DeclarationHandle.Create(Prefix + "original_normal_row"), H("original_normal_row"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("The same normal-row identity holds for every original source, input and detector occupation, with no finite-frequency replacement of the carrier."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-normal-row-source-original-corrected-normal-convolution"), DeclarationHandle.Create(Prefix + "original_corrected_normal_convolution"), H("original_corrected_normal_convolution"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("The actual oscillatorCorrected row is the finite sum over original charged Corr shifts and residual occupations, with coefficient_delta(Corr_s), the residual factorial and the normal Laurent row at e+2s+chargeNorm(a). Both external factorials remain outside the sum."))), DescribeRole.Theorem),
            Paragraph(Text("The proof compares the actual charged seed and signed-current recurrences with the independently defined Gaussian moments. Finite mode reindexing, the actual Gram-colour contraction and strong occupation induction identify the row. Restricted-coordinate and native-exponential normalization give the same coefficients on enlarged finite supports.")),
